begin;
select plan(13);
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000039','member39@example.com'),('00000000-0000-0000-0000-000000000139','outsider39@example.com');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000039',true);
set local role authenticated;
create temp table enroll_group as select * from create_group('Enrollment');
create temp table enroll_comp as select create_competition((select id from enroll_group),'Steps together','steps',current_date+2,current_date+9,'UTC') as id;
select is((select count(*)::int from competition_participants),0,'creator is not enrolled automatically');
select lives_ok($$select join_competition((select id from enroll_comp))$$,'explicit enrollment succeeds');
select lives_ok($$select join_competition((select id from enroll_comp))$$,'repeat enrollment is idempotent');
select is((select count(*)::int from competition_participants),1,'one participant row only');
select lives_ok($$select leave_competition((select id from enroll_comp))$$,'leave before end succeeds');
select is((select status from competition_participants),'left','history retains the opt-out');
select lives_ok($$select join_competition((select id from enroll_comp))$$,'rejoin before start succeeds');
delete from metric_shares where group_id=(select id from enroll_group) and metric='steps';
select throws_ok($$select join_competition((select id from enroll_comp))$$,'P0001','enable sharing for this metric in Group Info before joining','joining never bypasses sharing');
select throws_ok($$select create_competition((select id from enroll_group),'Weight','weight',current_date+2,current_date+3,'UTC')$$,'P0001','only steps competitions are enabled in version 1','unsupported metrics rejected');
select throws_ok($$select create_competition((select id from enroll_group),'Past','steps',current_date-2,current_date+3,'UTC')$$,'P0001','choose a future start day','past starts rejected');
grant select on enroll_group,enroll_comp to authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000139',true);
select throws_ok($$select join_competition((select id from enroll_comp))$$,'P0001','competition unavailable','outsider cannot enroll');
select lives_ok($$select competition_invite((select id from enroll_comp),(select invite_code from enroll_group))$$,'valid invitation permits metadata-only preview');
select throws_ok($$select competition_invite((select id from enroll_comp),'INVALID8')$$,'P0001','competition invitation unavailable','invalid invitation rejected');
select * from finish();
rollback;
